// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import path from "node:path";
import { defineConfig, env } from "prisma/config";
import { resolvePrismaCliDatabaseTarget } from "./lib/db/prismaCliGuard.ts";
import { DEVELOPMENT_ENV_FILE, readEnvFile, TEST_ENV_FILE } from "./lib/testing/integrationEnv.ts";

// KATANA_DB_TARGET=test のときだけ、.env.test の接続先を検証してから使う（失敗したら throw し、Prisma CLI は接続せずに終了する）。
// 未設定のときは従来どおり env("DATABASE_URL")。詳細は lib/db/prismaCliGuard.ts
const databaseTarget = resolvePrismaCliDatabaseTarget({
  env: process.env,
  argv: process.argv,
  readTestEnv: () => readEnvFile(path.join(process.cwd(), TEST_ENV_FILE)),
  readDevelopmentEnv: () => readEnvFile(path.join(process.cwd(), DEVELOPMENT_ENV_FILE)),
});

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: databaseTarget.mode === "test" ? databaseTarget.url : env("DATABASE_URL"),
  },
});
